/// <summary>
/// Table class for AVARUMDSDCodeTable, provides methods for existence checks, default creation, and record lookup.
/// </summary>
public class AVARUMDSDCodeTable extends common
{
}

Method.Source:
/// <summary>
/// Checks if a DSD code exists for the given class and code ID.
/// If not, triggers a failed check with a message.
/// </summary>
/// <param name="_codeClass">The DSD class.</param>
/// <param name="_dsdCodeId">The DSD code ID.</param>
/// <returns>True if exists, otherwise false.</returns>
static boolean checkExist(AVARUMDSDClass _codeClass, AVARUMDSDCodeId _dsdCodeId)
{
    if (_dsdCodeId && !AVARUMDSDCodeTable::exist(_codeClass, _dsdCodeId))
    {
        return Global::checkFailed(strfmt(AVARUMDSDCodeTable::txtNotExist(),_codeClass, _dsdCodeId));
    }

    return true;
}

/// <summary>
/// Helper method to create a DSD code record.
/// </summary>
/// <param name="_codeClass">The DSD class.</param>
/// <param name="_code">The DSD code ID.</param>
/// <param name="_txt">Description text.</param>
/// <param name="_feePerWeight">Fee weight value.</param>
private static void create(AVARUMDSDClass _codeClass, AVARUMDSDCodeId _code, Description _txt, Weight _feePerWeight)
{
    AVARUMDSDCodeTable dsdCode;

    dsdCode.clear();
    dsdCode.CodeClass = _codeClass;
    dsdCode.Code = _code;                 
    dsdCode.ValidFrom = DateTimeUtil::utcNow();
    dsdCode.ValidTo = DateTimeUtil::maxValue();
    dsdCode.Txt = _txt;
    dsdCode.FeePerWeight = _feePerWeight;
    dsdCode.insert();
}

/// <summary>
/// Creates default DSD code records if they do not already exist.
/// </summary>
public static void createDefaults()
{
    #DEFINE.G1('G.1')
    #DEFINE.G2('G.2')
    #DEFINE.G3('G.3')
    #DEFINE.G4('G.4')
    #DEFINE.G5('G.5')
    #DEFINE.G6('G.6')
    #DEFINE.G7('G.7')
    #DEFINE.G8('G.8')


    if (!AVARUMDSDCodeTable::exist(AVARUMDSDClass::Weight, #G1))
    {
        AVARUMDSDCodeTable::create(AVARUMDSDClass::Weight, #G1, "@AVARUM:DSDCodeText_G1", 0.07);
    }

    if (!AVARUMDSDCodeTable::exist(AVARUMDSDClass::Weight, #G2))
    {
        AVARUMDSDCodeTable::create(AVARUMDSDClass::Weight, #G2, "@AVARUM:DSDCodeText_G2", 0.18);
    }

    if (!AVARUMDSDCodeTable::exist(AVARUMDSDClass::Weight, #G3))
    {
        AVARUMDSDCodeTable::create(AVARUMDSDClass::Weight, #G3, "@AVARUM:DSDCodeText_G3", 0.27);
    }

    if (!AVARUMDSDCodeTable::exist(AVARUMDSDClass::Weight, #G4))
    {
        AVARUMDSDCodeTable::create(AVARUMDSDClass::Weight, #G4, "@AVARUM:DSDCodeText_G4", 0.73);
    }

    if (!AVARUMDSDCodeTable::exist(AVARUMDSDClass::Weight, #G5))
    {
        AVARUMDSDCodeTable::create(AVARUMDSDClass::Weight, #G5, "@AVARUM:DSDCodeText_G5", 1.30);
    }

    if (!AVARUMDSDCodeTable::exist(AVARUMDSDClass::Weight, #G6))
    {
        AVARUMDSDCodeTable::create(AVARUMDSDClass::Weight, #G6, "@AVARUM:DSDCodeText_G6", 0.75);
    }

    if (!AVARUMDSDCodeTable::exist(AVARUMDSDClass::Weight, #G7))
    {
        AVARUMDSDCodeTable::create(AVARUMDSDClass::Weight, #G7, "@AVARUM:DSDCodeText_G7", 1.01);
    }

    if (!AVARUMDSDCodeTable::exist(AVARUMDSDClass::Weight, #G8))
    {
        AVARUMDSDCodeTable::create(AVARUMDSDClass::Weight, #G8, "@AVARUM:DSDCodeText_G8", 0.10);
    }
}

/// <summary>
/// Checks if a DSD code record exists for the given class and code ID.
/// </summary>
/// <param name="_codeClass">The DSD class.</param>
/// <param name="_dsdCodeId">The DSD code ID.</param>
/// <returns>True if exists, otherwise false.</returns>
static boolean exist(AVARUMDSDClass _codeClass, AVARUMDSDCodeId _dsdCodeId)
{
    AVARUMDSDCodeTable dsdCode;
    boolean exist;

    if (_dsdCodeId)
    {
        select firstonly RecId from dsdCode
            where dsdCode.CodeClass == _codeClass && dsdCode.Code  == _dsdCodeId;

        exist = dsdCode.RecId ? true : false;
    }

    return exist;

}

/// <summary>
/// Finds and returns a DSD code record for the specified class and code ID, valid at the given date.
/// </summary>
/// <param name="_codeClass">The DSD class to search for.</param>
/// <param name="_dsdCodeId">The DSD code ID to search for.</param>
/// <param name="_fromDate">The from date for valid time state. Defaults to current UTC date and time.</param>
/// <param name="_toDate">The to date for valid time state. Defaults to max UTC date and time.</param>
/// <param name="_forUpdate">Indicates whether the record should be selected for update.</param>
/// <returns>
/// The <c>AVARUMDSDCodeTable</c> record matching the specified class and code ID, or an empty record if not found.
/// </returns>
static AVARUMDSDCodeTable find
(
    AVARUMDSDClass _codeClass, 
    AVARUMDSDCodeId _dsdCodeId, 
    utcDateTime _fromDate = DateTimeUtil::utcNow(), 
    utcDateTime _toDate = DateTimeUtil::maxValue(),
    boolean _forUpdate = false
)
{
    AVARUMDSDCodeTable dsdCode;

    if (_dsdCodeId)
    {
        dsdCode.selectForUpdate(_forUpdate);

        select firstonly validtimestate(_fromdate, _toDate) * from dsdCode
            where dsdCode.CodeClass == _codeClass &&
                dsdCode.Code  == _dsdCodeId;
    }

    return dsdCode;
}

/// <summary>
/// Gets the text message for a non-existent DSD code.
/// </summary>
/// <returns>Localized message string.</returns>
static str txtNotExist()
{
    return "@AVARUM:ClassNotExist";
}
